<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Registrar compra | Deportes Total</title>
<style>
*{box-sizing:border-box;font-family:Arial,Helvetica,sans-serif}body{margin:0;background:#eef1f3;color:#263238}.topbar{background:#263f59;color:#fff;padding:15px 25px;border-bottom:4px solid #1b3045}.topbar a{float:right;color:#fff;text-decoration:none}.container{max-width:1000px;margin:28px auto;padding:0 18px}.card{background:#fff;border:1px solid #cbd3da;padding:22px;margin-bottom:18px}h2,h3{color:#263f59;margin-top:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.field{margin-bottom:14px}.field label{display:block;font-weight:bold;margin-bottom:6px}.field input,.field select{width:100%;padding:11px;border:1px solid #bdc8d1;border-radius:3px}.btn{display:inline-block;padding:10px 14px;background:#315f85;color:#fff;border:0;border-radius:3px;cursor:pointer;text-decoration:none;font-weight:bold}.btn.gray{background:#687783}.btn.red{background:#a93636}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e3e7ea}th{background:#e9eef2;font-size:12px;text-transform:uppercase}.msg{padding:12px;margin-bottom:15px;background:#ffeded;border-left:4px solid #b33}.total{text-align:right;font-size:22px;font-weight:bold;color:#263f59;margin:16px 0}.muted{color:#6c7a86;font-size:13px}@media(max-width:650px){.grid{grid-template-columns:1fr}.topbar{display:block}.scroll table{min-width:650px}}
</style><link rel="stylesheet" href="<?= base_url('assets/css/app-sidebar.css') ?>">
</head><body class="app-layout">
<?php $this->load->view('partials/sidebar'); ?><header class="topbar"><strong>DEPORTES TOTAL | Registrar compra</strong><a href="<?= site_url('compras') ?>">Volver a compras</a></header><main class="container">
<h2>Nueva compra de mercancía</h2><p class="muted">Al guardar, las cantidades se sumarán automáticamente al inventario y quedará registrado el movimiento de entrada.</p>

<?php if (empty($proveedores)): ?><div class="card">No hay proveedores activos. <a href="<?= site_url('compras/proveedores') ?>">Registra un proveedor primero.</a></div><?php elseif (empty($productos)): ?><div class="card">No hay productos activos. Registra productos antes de registrar una compra.</div><?php else: ?>
<form method="post" action="<?= site_url('compras/guardar') ?>" id="formCompra"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>">
<section class="card"><div class="grid"><div class="field"><label>Proveedor</label><select name="proveedor_id" required><option value="">Selecciona proveedor</option><?php foreach($proveedores as $p): ?><option value="<?= (int)$p->id ?>"><?= html_escape($p->nombre) ?><?= $p->nit ? ' · '.$p->nit : '' ?></option><?php endforeach; ?></select></div><div class="field"><label>Observaciones</label><input name="observaciones" maxlength="250" placeholder="Ej. Reposición de temporada"></div></div></section>
<section class="card"><h3>Productos recibidos</h3><div class="scroll"><table><thead><tr><th>Producto / referencia / talla</th><th>Cantidad</th><th>Costo unitario</th><th>Subtotal</th><th></th></tr></thead><tbody id="itemsBody"></tbody></table></div><p><button type="button" class="btn gray" id="agregar">+ Agregar producto</button></p><div class="total">Total compra: <span id="totalCompra">$0</span></div></section>
<button type="submit" class="btn">Registrar compra y actualizar inventario</button> <a class="btn gray" href="<?= site_url('compras') ?>">Cancelar</a></form>
<?php endif; ?></main>
<script>
var productos=<?= json_encode($productos, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>, contador=0;
function pesos(v){return '$'+Number(v).toLocaleString('es-CO',{maximumFractionDigits:0});}
function recalcular(){var total=0;document.querySelectorAll('#itemsBody tr').forEach(function(tr){var cantidad=Number(tr.querySelector('.cantidad').value||0),costo=Number(tr.querySelector('.costo').value||0),sub=cantidad*costo;total+=sub;tr.querySelector('.subtotal').textContent=pesos(sub);});document.getElementById('totalCompra').textContent=pesos(total);}
function agregar(){var tr=document.createElement('tr'),html='<td><select name="items['+contador+'][producto_id]" required><option value="">Selecciona</option>';productos.forEach(function(p){html+='<option value="'+p.id+'">'+p.nombre+' | '+p.referencia+' | Talla '+p.talla+'</option>';});html+='</select></td><td><input class="cantidad" type="number" name="items['+contador+'][cantidad]" min="1" step="1" value="1" required></td><td><input class="costo" type="number" name="items['+contador+'][costo]" min="1" step="1" required></td><td class="subtotal">$0</td><td><button type="button" class="btn red quitar">X</button></td>';tr.innerHTML=html;document.getElementById('itemsBody').appendChild(tr);contador++;tr.querySelector('.cantidad').addEventListener('input',recalcular);tr.querySelector('.costo').addEventListener('input',recalcular);tr.querySelector('.quitar').addEventListener('click',function(){tr.remove();recalcular();});}
var b=document.getElementById('agregar');if(b){b.addEventListener('click',agregar);agregar();document.getElementById('formCompra').addEventListener('submit',function(e){if(document.querySelectorAll('#itemsBody tr').length===0){e.preventDefault();alert('Agrega al menos un producto.');}});}
</script></body></html>
